<?php

declare(strict_types=1);

namespace NoResponse\LateResults;

/**
 * Runs one action in an identity provider. Build one with LateResults::identityProvider or
 * LateResults::customProvider. Generated by tools/generate_overlays.py; do not edit.
 */
interface ActionProvider
{
    /** clerk, workos, auth0 or custom. */
    public function name(): string;

    /**
     * Take the action and return any other action that had to run with it (Auth0 restricts to end a session).
     *
     * @return list<string>
     */
    public function run(string $action, string $userId): array;
}
